CREATE PROCEDURE "DA_APRIORI_CALL" (IN SCHEMANAME VARCHAR(100), IN DATA_TABLE_NAME VARCHAR(50), IN CONTROL_TABLE_NAME VARCHAR(50)) LANGUAGE SQLSCRIPT  SQL SECURITY INVOKER  AS BEGIN     DECLARE ROWCNT INTEGER;     DECLARE APRIORI_CONTROL_TABLE DA_APRIORI_CONTROL_T;         DECLARE APRIORI_DATA_TABLE DA_APRIORI_DATA_T;     DECLARE APRIORI_RESULT_TABLE DA_APRIORI_RESULT_T;     DECLARE APRIORI_PMMLMODEL_TABLE DA_APRIORI_PMMLMODEL_T;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#TEMP_APRIORI_CONTROL_TABLE' AND CONNECTION_ID=CURRENT_CONNECTION;     IF ROWCNT>0 THEN         DROP TABLE #TEMP_APRIORI_CONTROL_TABLE;     END IF;     CREATE LOCAL TEMPORARY COLUMN TABLE #TEMP_APRIORI_CONTROL_TABLE LIKE DA_APRIORI_CONTROL_T;     EXECUTE IMMEDIATE 'INSERT INTO #TEMP_APRIORI_CONTROL_TABLE SELECT * FROM '||:CONTROL_TABLE_NAME;     APRIORI_CONTROL_TABLE = SELECT * FROM #TEMP_APRIORI_CONTROL_TABLE;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#TEMP_APRIORI_DATA_TABLE' AND CONNECTION_ID=CURRENT_CONNECTION;     IF ROWCNT>0 THEN         DROP TABLE #TEMP_APRIORI_DATA_TABLE;     END IF;     CREATE LOCAL TEMPORARY COLUMN TABLE #TEMP_APRIORI_DATA_TABLE LIKE DA_APRIORI_DATA_T;     EXECUTE IMMEDIATE 'INSERT INTO #TEMP_APRIORI_DATA_TABLE SELECT * FROM '||:DATA_TABLE_NAME;     APRIORI_DATA_TABLE = SELECT * FROM #TEMP_APRIORI_DATA_TABLE;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#TEMP_APRIORI_RESULT_TABLE' AND CONNECTION_ID=CURRENT_CONNECTION;     IF ROWCNT>0 THEN         DROP TABLE #TEMP_APRIORI_RESULT_TABLE;     END IF;     CREATE LOCAL TEMPORARY COLUMN TABLE #TEMP_APRIORI_RESULT_TABLE LIKE DA_APRIORI_RESULT_T;     CALL DA_APRIORI_RULE_PROC(:APRIORI_DATA_TABLE, :APRIORI_CONTROL_TABLE, :APRIORI_RESULT_TABLE, :APRIORI_PMMLMODEL_TABLE);     INSERT INTO #TEMP_APRIORI_RESULT_TABLE SELECT * FROM :APRIORI_RESULT_TABLE;     SELECT '#TEMP_APRIORI_RESULT_TABLE' AS RESULT_TABLE_NAME FROM DUMMY; END
